    v_oid := to_regprocedure(v_fn.sig);
    SELECT prosrc, proacl::text, prosecdef, provolatile, prolang, proconfig
      INTO v_src, v_acl, v_def, v_vol, v_lang, v_cfg FROM pg_proc WHERE oid = v_oid;
    IF md5(v_src) <> v_fn.m1 THEN
      RAISE EXCEPTION '074a rollback: % is not the text 074a wrote after hook % (md5 %) - stop, re-measure', v_fn.sig, v_fn.k, md5(v_src);
    END IF;
    IF (length(v_src) - length(replace(v_src, v_fn.b, ''))) <> length(v_fn.b) THEN
      RAISE EXCEPTION '074a rollback: hook % of % is not there exactly once - stop', v_fn.k, v_fn.sig;
    END IF;
    v_old := replace(v_src, v_fn.b, v_fn.a);
    IF md5(v_old) <> v_fn.m0 THEN
      RAISE EXCEPTION '074a rollback: % would not return to its text before hook % (md5 %) - stop', v_fn.sig, v_fn.k, md5(v_old);
    END IF;
